-- solo-wow Mythic+ raid item ranks (scripts/Custom/MythicPlus): the equippable rares and epics of each Wrath
-- raid difficulty the Great Vault's Raids row counts (MythicVaultPolicy.h; 0 10N, 1 25N, 2 10H, 3 25H).
-- Generated by solo-wow tools/mythic-plus/generate_items.py. Append only: `idx` is the item's raid rank-id
-- index (MythicItemPolicy.h), stored in players' bags, so an item never moves or leaves.
CREATE TABLE IF NOT EXISTS `mythic_plus_raid_item` (
  `idx` INT UNSIGNED NOT NULL,
  `entry` INT UNSIGNED NOT NULL COMMENT 'item_template entry of the real item',
  `map` SMALLINT UNSIGNED NOT NULL COMMENT 'raid whose loot it is',
  `difficulty` TINYINT UNSIGNED NOT NULL COMMENT 'raid difficulty whose loot it is',
  PRIMARY KEY (`idx`),
  UNIQUE KEY `loot` (`entry`, `map`, `difficulty`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='solo-wow Great Vault raid items with generated ranks';

DELETE FROM `mythic_plus_raid_item`;
